HWND WINAPI GetDlgItem( HWND hwndDlg, INT id )
{
    HWND hwnd = GetWindow( hwndDlg, GW_CHILD );

    if (hwnd) hwnd = DIALOG_IdToHwnd( hwnd, id, FALSE );
    return hwnd;
}

